{
  "narrative_summary": "Automate Tier One Triage produced the best outcome in 64% of runs of this model, and Hire Two Support Engineers produced the best outcome in 36% of runs. The link from Automation Coverage to Response Time is sensitive to your assumptions, worth checking before acting.",
  "story_headlines": {
    "opt_automate": "Automate Tier One Triage cuts response time by lifting automation coverage directly.",
    "opt_hire": "Hire Two Support Engineers would need ticket volume growth to change this model's outcome."
  },
  "robustness_explanation": {
    "summary": "The ordering holds in about 73% of variations, a moderate result given the modelled confidence.",
    "primary_risk": "The link from Automation Coverage to Response Time could shift which option this model points to.",
    "stability_factors": ["Ticket Volume shows a well evidenced connection to Response Time"],
    "fragility_factors": ["The link from Automation Coverage to Response Time is not fully settled"]
  },
  "readiness_rationale": "The comparison is settled enough to act on, though Automation Coverage still carries a gap worth closing, and its intervention values are placeholders you have not yet set.",
  "evidence_enhancements": {
    "fac_automation_rate": {
      "specific_action": "Pilot Tier One triage automation on a limited ticket slice and measure actual coverage achieved.",
      "rationale": "This factor's link to Response Time is not yet firm, and the options use placeholder values for it.",
      "evidence_type": "internal_data",
      "decision_hygiene": "Estimate the coverage rate before running the pilot, then compare against the result."
    }
  },
  "scenario_contexts": {
    "edge_automation_response": {
      "trigger_description": "If the link from Automation Coverage to Response Time proves weaker than modelled...",
      "consequence": "...then this model points to Hire Two Support Engineers rather than Automate Tier One Triage."
    }
  },
  "flip_thresholds": [
    {
      "factor_id": "fac_automation_rate",
      "factor_label": "Automation Coverage",
      "current_display": "58%",
      "flip_display": "31%",
      "narrative": "If Automation Coverage moves from 58% to 31%, this model points to a different option."
    }
  ],
  "bias_findings": [],
  "key_assumptions": [
    "The link from Automation Coverage to Response Time assumes current triage patterns hold once automated.",
    "Automate Tier One Triage's intervention values are placeholders, not yet confirmed by you.",
    "The link from Ticket Volume to Response Time assumes no major shift in incoming ticket mix."
  ],
  "decision_quality_prompts": [
    {
      "question": "What would make you switch to Hire Two Support Engineers?",
      "principle": "Consider-the-opposite",
      "applies_because": "Automate Tier One Triage's own share is above the level where checking the opposite case is most useful."
    },
    {
      "question": "This failed because... what happened to Automation Coverage in the months after launch?",
      "principle": "Pre-mortem (Klein)",
      "applies_because": "The comparison is settled enough to act on, so stress-testing the failure story is worthwhile now."
    }
  ],
  "pre_mortem": {
    "failure_scenario": "Automate Tier One Triage failed because Automation Coverage never reached the modelled level, leaving Response Time largely unchanged.",
    "warning_signs": ["Automation Coverage plateaus well below the pilot target", "Ticket Volume rises faster than triage automation can absorb"],
    "mitigation": "Set a coverage checkpoint early in the pilot before committing further budget.",
    "grounded_in": ["edge_automation_response", "fac_automation_rate"],
    "review_trigger": "Reconvene if pilot coverage falls short before the next planning cycle."
  }
